mapper.select:
WITH YZ AS ( SELECT t1.EVENT_ID,t1.OCCUPY_CODE FROM RSK_OCCUPY_INFO t1 INNER JOIN RSK_PRE_OCCUPY_INFO t2 ON t1.OCCUPY_CODE = t2.EVENT_ID LEFT JOIN ( select ENTRUST_ID,ENTRUST_STATUS FROM ETR_ENTRUST UNION ALL select B.ENTRUST_ID||B.PORTFOLIO_ID ENTRUST_ID,A.ENTRUST_STATUS FROM ETR_ENTRUST_WW A, ETR_ENTRUST_WW_DETAIL B WHERE A.ENTRUST_ID=B.ENTRUST_ID ) etr ON t2.EVENT_ID = etr.ENTRUST_ID OR SUBSTR(t2.EVENT_ID,0,LENGTH(t2.EVENT_ID)-3) = etr.ENTRUST_ID WHERE t2.OCCUPY_DATE >= #{sysDate,jdbcType=DATE} AND etr.ENTRUST_STATUS NOT IN ('04', '06', '07') ), SF AS ( SELECT rpoi.EVENT_ID FROM RSK_PRE_OCCUPY_INFO rpoi LEFT JOIN ( select ENTRUST_ID,ENTRUST_STATUS FROM ETR_ENTRUST UNION ALL select B.ENTRUST_ID||B.PORTFOLIO_ID ENTRUST_ID,A.ENTRUST_STATUS FROM ETR_ENTRUST_WW A, ETR_ENTRUST_WW_DETAIL B WHERE A.ENTRUST_ID=B.ENTRUST_ID ) etr ON etr.ENTRUST_ID = rpoi.EVENT_ID OR SUBSTR(rpoi.EVENT_ID,0,LENGTH(rpoi.EVENT_ID)-3) = etr.ENTRUST_ID WHERE rpoi.OCCUPY_DATE >= #{sysDate,jdbcType=DATE} AND etr.ENTRUST_STATUS NOT IN ('04', '06', '07') ) -- 预占部分 SELECT rpoi.UUID orderNo, -- 序号 rpoi.EVENT_ID eventId, -- 事件编号 null preOccupyCode, -- 实占对应的预占编号 irl.REQUEST_DATA requestData, -- 报文 irl.INF_ID infCode, -- 接口代码 irl.SEQ_NO seqNo -- 报文流水号 FROM RSK_PRE_OCCUPY_INFO rpoi LEFT JOIN INTERF_RISK_LOG irl ON irl.SEQ_NO = rpoi.SEQ_NO WHERE irl.RESPONSE_DATA IS NULL AND irl.SEQ_NO IS NOT NULL AND rpoi.EVENT_DATE < #{sysDate,jdbcType=DATE} AND EXISTS (SELECT 1 FROM SF WHERE SF.EVENT_ID = rpoi.EVENT_ID )
AND rpoi.PROD_ID IN
#{item}
UNION ALL -- 实占部分 SELECT rpoi.UUID orderNo, -- 序号 rpoi.EVENT_ID eventId, -- 事件编号 t1.OCCUPY_CODE preOccupyCode, -- 实占对应的预占编号 irl.REQUEST_DATA requestData, -- 报文 irl.INF_ID infCode, -- 接口代码 irl.SEQ_NO seqNo -- 报文流水号 FROM RSK_OCCUPY_INFO rpoi LEFT JOIN INTERF_RISK_LOG irl ON irl.SEQ_NO = rpoi.SEQ_NO LEFT JOIN YZ t1 ON t1.EVENT_ID = rpoi.EVENT_ID WHERE irl.RESPONSE_DATA IS NULL AND irl.SEQ_NO IS NOT NULL AND rpoi.EVENT_DATE < #{sysDate,jdbcType=DATE} AND EXISTS (SELECT 1 FROM YZ WHERE YZ.EVENT_ID = rpoi.EVENT_ID )
AND rpoi.PROD_ID IN
#{item}

